// Emits Prometheus recording and alerting rules from validated SLO definitions.
// Pure: returns file contents keyed by relative path. The CLI does the writing.
import { stringify } from 'yaml';
import { resolveTiers, windowToHours, errorBudget, clean } from './burn-rate.mjs';

export const GENERATED_HEADER =
  '# GENERATED by tooling/observability/generate.mjs from infra/observability/slos/slos.yaml.\n' +
  '# Do not edit by hand: change the SLO file and re-run the generator.\n';

const WINDOW_TOKEN = '{{window}}';

export function pascal(id) {
  return id
    .split('-')
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join('');
}

function substitute(template, window) {
  return template.split(WINDOW_TOKEN).join(window);
}

function bucketLabel(seconds) {
  return String(seconds);
}

/** PromQL for the error ratio and the event rate of a ratio or latency SLO over one window. */
export function sliExpressions(slo, window) {
  if (slo.kind === 'ratio') {
    const bad = substitute(slo.sli.bad, window);
    const total = substitute(slo.sli.total, window);
    return { error: `(${bad}) / (${total})`, events: `${total}` };
  }
  if (slo.kind === 'latency') {
    const sel = slo.sli.selector;
    const countSel = sel === '' ? '' : `{${sel}}`;
    const bucketSel = `{${sel === '' ? '' : `${sel},`}le="${bucketLabel(slo.sli.thresholdSeconds)}"}`;
    const total = `sum(rate(${slo.sli.histogram}_count${countSel}[${window}]))`;
    const good = `sum(rate(${slo.sli.histogram}_bucket${bucketSel}[${window}]))`;
    return { error: `1 - (${good} / ${total})`, events: total };
  }
  throw new Error(`sliExpressions: unsupported kind ${slo.kind}`);
}

function windowsFor(file) {
  const set = new Set([file.period]);
  for (const tier of file.tiers) {
    set.add(tier.long);
    set.add(tier.short);
  }
  return [...set].sort((a, b) => windowToHours(a) - windowToHours(b));
}

function annotations(slo, summary, description) {
  return {
    summary,
    description,
    runbook: slo.runbook,
    dashboard: `outlet-${slo.dashboard}`,
    spec_row: slo.specRow,
  };
}

function recordingGroup(slo, windows) {
  const rules = [];
  for (const w of windows) {
    const { error, events } = sliExpressions(slo, w);
    const labels = { slo: slo.id, journey: slo.journey };
    rules.push({ record: `slo:sli_error:ratio_rate${w}`, expr: error, labels });
    rules.push({ record: `slo:sli_events:rate${w}`, expr: events, labels });
  }
  return { name: `slo-${slo.id}-recording`, interval: '30s', rules };
}

function burnAlertGroup(slo, file) {
  const periodHours = windowToHours(file.period);
  const tiers = resolveTiers({ objective: slo.objective, periodHours, tiers: file.tiers });
  const rules = [];
  for (const tier of tiers) {
    const severity = tier.name === 'fast' ? 'page' : slo.slowSeverity;
    const errAt = (w) => `slo:sli_error:ratio_rate${w}{slo="${slo.id}"}`;
    const parts = [
      `${errAt(tier.long)} > ${tier.threshold}`,
      `${errAt(tier.short)} > ${tier.threshold}`,
    ];
    if (slo.minEventsPerWindow > 0) {
      parts.push(
        `slo:sli_events:rate${tier.long}{slo="${slo.id}"} * ${clean(tier.longHours * 3600)} >= ${slo.minEventsPerWindow}`,
      );
    }
    rules.push({
      alert: `SLO${pascal(tier.name)}Burn${pascal(slo.id)}`,
      expr: parts.join('\n  and\n'),
      for: tier.for,
      labels: {
        severity,
        slo: slo.id,
        journey: slo.journey,
        tier: tier.name,
        burn_rate: String(tier.burnRate),
      },
      annotations: annotations(
        slo,
        `${slo.title}: error budget burning at ${tier.burnRate}x over ${tier.long} and ${tier.short}`,
        `Error ratio above ${tier.threshold} (burn rate ${tier.burnRate} x budget ${errorBudget(slo.objective)}) ` +
          `on both the ${tier.long} and ${tier.short} windows. At this rate the ${file.period} budget is gone in ` +
          `${clean(periodHours / tier.burnRate)} hours.`,
      ),
    });
  }
  if (slo.alertOnAbsent) {
    rules.push({
      alert: `SLONoData${pascal(slo.id)}`,
      expr: `absent_over_time(slo:sli_events:rate5m{slo="${slo.id}"}[1h])`,
      for: '5m',
      labels: { severity: 'ticket', slo: slo.id, journey: slo.journey, tier: 'absent' },
      annotations: annotations(
        slo,
        `${slo.title}: no SLI data for 1h`,
        'The SLI produced no events for an hour. Either traffic stopped or instrumentation broke; the burn-rate alerts are blind until this is resolved.',
      ),
    });
  }
  return { name: `slo-${slo.id}-alerts`, rules };
}

function zeroGaugeGroups(slo) {
  const rules = slo.alerts.map((a) => ({
    alert: `SLOZeroBreach${pascal(slo.id)}After${a.for}`,
    expr: `${slo.sli.gauge} > 0`,
    for: a.for,
    labels: { severity: a.severity, slo: slo.id, journey: slo.journey, tier: `zero-${a.for}` },
    annotations: annotations(
      slo,
      `${slo.title}: non-zero for ${a.for}`,
      'This SLO has an objective of exactly zero; any non-zero value is a breach and needs a human.',
    ),
  }));
  return [{ name: `slo-${slo.id}-alerts`, rules }];
}

export function generateRuleFiles(file) {
  const windows = windowsFor(file);
  const out = {};
  for (const slo of file.slos) {
    const groups =
      slo.kind === 'zero_gauge'
        ? zeroGaugeGroups(slo)
        : [recordingGroup(slo, windows), burnAlertGroup(slo, file)];
    out[`slo-${slo.id}.rules.yaml`] =
      GENERATED_HEADER + stringify({ groups }, { lineWidth: 0, aliasDuplicateObjects: false });
  }
  return out;
}
